@import 'c/ihStyles';

/* ---------- two-pane layout ---------- */
.how {
    display: grid;
    grid-template-columns: minmax(240px, 300px) minmax(0, 1fr);
    gap: 16px;
    align-items: start;
}
.how_narrow {
    grid-template-columns: minmax(0, 1fr);
}
@media (max-width: 800px) {
    .how {
        grid-template-columns: minmax(0, 1fr);
    }
}

/* ---------- index (stepper) ---------- */
.index {
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 14px;
    position: sticky;
    top: 12px;
    max-height: calc(100vh - 24px);
    overflow-y: auto;
}
.groups {
    list-style: none;
    margin: 0;
    padding: 0;
}
.group {
    position: relative;
    padding-bottom: 14px;
}
/* the vertical line from this circle down to the next one */
.group::before {
    content: '';
    position: absolute;
    left: 13px;
    top: 28px;
    bottom: 0;
    width: 2px;
    background: var(--ih-line);
}
.group_last::before {
    bottom: 14px;
}
.group_done::before,
.group_current::before {
    background: var(--ih-brand);
}
.g-head,
.topic {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    background: none;
    border: none;
    padding: 0;
    font: inherit;
    text-align: left;
    cursor: pointer;
    color: var(--ih-ink);
}
.g-head {
    position: relative;
    z-index: 1;
    padding: 2px 0;
}
.g-badge {
    flex: none;
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    border: 2px solid var(--ih-line);
    background: var(--ih-surface);
    color: var(--ih-quiet);
    font-size: 12px;
    font-weight: 700;
}
.group_read .g-badge {
    background: var(--ih-brand);
    border-color: var(--ih-brand);
    color: #ffffff;
}
.group_current .g-badge {
    border-color: var(--ih-brand);
    color: var(--ih-brand);
    box-shadow: 0 0 0 3px var(--ih-brand-soft);
}
.g-name {
    font-weight: 700;
    font-size: 14px;
}
.group_current .g-name {
    color: var(--ih-brand);
}
.topics {
    list-style: none;
    margin: 6px 0 0;
    padding: 0;
}
.topic {
    position: relative;
    padding: 5px 8px 5px 0;
    border-radius: 6px;
    font-size: 13px;
    color: var(--ih-ink-2);
}
.topic:hover {
    background: var(--ih-line-2);
}
.topic:focus-visible,
.g-head:focus-visible {
    outline: 2px solid var(--ih-brand);
    outline-offset: 2px;
}
.dot {
    flex: none;
    box-sizing: border-box;
    position: relative;
    z-index: 1;
    width: 8px;
    height: 8px;
    margin: 0 20px 0 10px;
    border-radius: 50%;
    border: 2px solid var(--ih-line);
    background: var(--ih-surface);
}
.topic_seen .dot {
    border-color: var(--ih-brand);
    background: var(--ih-brand);
}
.topic_on {
    background: var(--ih-brand-soft);
    color: var(--ih-brand);
    font-weight: 600;
}
.topic_on:hover {
    background: var(--ih-brand-soft);
}
.topic_on .dot {
    border-color: var(--ih-brand);
    background: var(--ih-brand);
    box-shadow: 0 0 0 3px var(--ih-surface);
}
.no-match {
    margin: 0;
}
.progress {
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-top: 1px solid var(--ih-line-2);
    padding-top: 10px;
}
.reset {
    background: none;
    border: none;
    padding: 0;
    font: inherit;
    font-size: 12px;
}

/* ---------- topic pane ---------- */
.pane {
    padding: 20px 24px;
    display: flex;
    flex-direction: column;
    gap: 14px;
    scroll-margin-top: 12px;
}
.combo {
    max-width: 480px;
}
.crumb {
    margin-bottom: -10px;
}
.title {
    margin: 0;
    font-size: 20px;
    font-weight: 700;
    line-height: 1.3;
}
.lead {
    margin: -6px 0 0;
    font-size: 14px;
    color: var(--ih-ink-2);
}
.points {
    list-style: disc;
    margin: 0;
    padding-left: 18px;
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.block {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
}
.block-title {
    margin: 0;
    font-size: 13px;
    font-weight: 700;
}
.table-box {
    border: 1px solid var(--ih-line);
    border-radius: 8px;
}
.cell {
    vertical-align: top;
    overflow-wrap: anywhere;
}
.code-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
}
.tip {
    margin: 0;
}
.go {
    display: flex;
}

/* ---------- chooser ---------- */
.chooser {
    display: flex;
    flex-direction: column;
    gap: 14px;
}
.question {
    padding: 12px 14px;
    border: 1px solid var(--ih-line);
    border-radius: 8px;
}

/* ---------- pictures and downloads ---------- */
.pictures {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 12px;
}
.picture {
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.picture img {
    width: 100%;
    border: 1px solid var(--ih-line);
    border-radius: 6px;
}
.downloads {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.download-buttons {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

/* ---------- Previous / Next ---------- */
.pager {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    margin-top: 6px;
    padding-top: 14px;
    border-top: 1px solid var(--ih-line-2);
}

.pdf {
    margin-left: 8px;
}
